from donations import load_donations, ROWS
from paging import all_pages, page_count


def test_last_items_present():
    pages = all_pages(list(load_donations()), 4)
    assert [x.pounds for p in pages for x in p] == [v for _, v in ROWS]


def test_partial_page_counted():
    assert page_count(7, 3) == 3 and page_count(1, 3) == 1


def test_exact_fit():
    assert page_count(6, 3) == 2 and page_count(3, 3) == 1


def test_no_empty_page():
    assert all(len(p) > 0 for p in all_pages(list(load_donations())[:4], 2))


def test_no_items():
    assert page_count(0, 3) == 0

